// Formal properties for rr_arbiter, derived from interface_spec.md.
// Immediate assertions only (open Yosys front end). No assumptions.
`default_nettype none
module rr_arbiter_props (
    input wire       clk,
    input wire       rst_n,
    input wire [2:0] req
);
    wire [2:0] grant;
    wire [1:0] last;

    rr_arbiter dut (
        .clk  (clk),
        .rst_n(rst_n),
        .req  (req),
        .grant(grant),
        .last (last)
    );

    // ------------------------------------------------------------------
    // Bookkeeping
    // ------------------------------------------------------------------
    reg f_past_valid = 1'b0;
    reg f_reset_seen = 1'b0;
    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n)
            f_reset_seen <= 1'b1;
    end

    // Spec priority order: last+1, last+2, last (mod 3)
    wire [1:0] f_first  = (last == 2'd2) ? 2'd0 : (last + 2'd1);
    wire [1:0] f_second = (last == 2'd0) ? 2'd2 :
                          ((last == 2'd1) ? 2'd0 : 2'd1);
    wire [2:0] f_first_bit  = 3'b001 << f_first;
    wire [2:0] f_second_bit = 3'b001 << f_second;
    wire [2:0] f_last_bit   = 3'b001 << last;

    wire f_grant_onehot = (grant != 3'b000) &&
                          ((grant & (grant - 3'b001)) == 3'b000);
    wire [1:0] f_gidx = grant[0] ? 2'd0 : (grant[1] ? 2'd1 : 2'd2);

    // ------------------------------------------------------------------
    // Combinational grant properties (2.2)
    // ------------------------------------------------------------------
    always @(*) begin
        // [req:RR-ONLY-REQUESTERS]
        assert ((grant & ~req) == 3'b000);

        if (f_reset_seen) begin
            // helper: last is 0, 1 or 2 once reset has been applied
            assert (last != 2'd3);

            // [req:RR-IDLE]
            if (req == 3'b000)
                assert (grant == 3'b000);

            // [req:RR-PICK] exactly one grant when any request
            if (req != 3'b000)
                assert (f_grant_onehot);

            // [req:RR-PICK] first requester in rotation order
            if (req[f_first])
                assert (grant == f_first_bit);
            if (!req[f_first] && req[f_second])
                assert (grant == f_second_bit);
            if (!req[f_first] && !req[f_second] && req[last])
                assert (grant == f_last_bit);
        end
    end

    // ------------------------------------------------------------------
    // Sequential properties (2.1, 2.3)
    // ------------------------------------------------------------------
    always @(posedge clk) begin
        if (f_past_valid) begin
            // [req:RR-RESET]
            if (!$past(rst_n))
                assert (last == 2'd2);

            // [req:RR-ROTATE]
            if ($past(rst_n) && $past(f_reset_seen) && ($past(grant) != 3'b000))
                assert (last == $past(f_gidx));

            // [req:RR-HOLD]
            if ($past(rst_n) && ($past(grant) == 3'b000))
                assert (last == $past(last));

            // [req:RR-YIELD]
            if ($past(rst_n) && $past(f_reset_seen) && ($past(grant) != 3'b000)
                && ((req & ~$past(grant)) != 3'b000))
                assert ((grant & $past(grant)) == 3'b000);
        end
    end

    // ------------------------------------------------------------------
    // Bounded wait (2.4): cycles a requester has held req without grant
    // ------------------------------------------------------------------
    reg [1:0] f_wait0 = 2'd0;
    reg [1:0] f_wait1 = 2'd0;
    reg [1:0] f_wait2 = 2'd0;

    always @(posedge clk) begin
        if (!rst_n || !f_reset_seen || !req[0] || grant[0])
            f_wait0 <= 2'd0;
        else
            f_wait0 <= f_wait0 + 2'd1;

        if (!rst_n || !f_reset_seen || !req[1] || grant[1])
            f_wait1 <= 2'd0;
        else
            f_wait1 <= f_wait1 + 2'd1;

        if (!rst_n || !f_reset_seen || !req[2] || grant[2])
            f_wait2 <= 2'd0;
        else
            f_wait2 <= f_wait2 + 2'd1;
    end

    always @(*) begin
        if (f_reset_seen) begin
            // [req:RR-BOUND] at most two grants to others, granted on the third
            assert (f_wait0 <= 2'd2);
            assert (f_wait1 <= 2'd2);
            assert (f_wait2 <= 2'd2);
            if ((f_wait0 == 2'd2) && req[0])
                assert (grant[0]);
            if ((f_wait1 == 2'd2) && req[1])
                assert (grant[1]);
            if ((f_wait2 == 2'd2) && req[2])
                assert (grant[2]);

            // helper invariants for induction
            if (f_wait0 == 2'd2)
                assert (f_first == 2'd0);
            if (f_wait1 == 2'd2)
                assert (f_first == 2'd1);
            if (f_wait2 == 2'd2)
                assert (f_first == 2'd2);
            if (f_wait0 == 2'd1)
                assert (last != 2'd0);
            if (f_wait1 == 2'd1)
                assert (last != 2'd1);
            if (f_wait2 == 2'd1)
                assert (last != 2'd2);
        end else begin
            // helper: counters idle before the first reset
            assert (f_wait0 == 2'd0);
            assert (f_wait1 == 2'd0);
            assert (f_wait2 == 2'd0);
        end
    end

    // ------------------------------------------------------------------
    // Covers: scenarios the proof must still allow
    // ------------------------------------------------------------------
    always @(posedge clk) begin
        if (f_reset_seen) begin
            cover (req == 3'b000);
            cover (grant == 3'b001);
            cover (grant == 3'b010);
            cover (grant == 3'b100);
            cover ((req == 3'b111) && (last == 2'd0));
            cover ((req == 3'b111) && (last == 2'd1));
            cover ((req == 3'b111) && (last == 2'd2));
            cover ((f_wait0 == 2'd2) && req[0]);
            cover ((f_wait1 == 2'd2) && req[1]);
            cover ((f_wait2 == 2'd2) && req[2]);
        end
        if (f_past_valid) begin
            cover (!$past(rst_n));
            cover ($past(rst_n) && $past(f_reset_seen) && ($past(grant) != 3'b000)
                   && ((req & ~$past(grant)) != 3'b000));
            cover ($past(rst_n) && $past(f_reset_seen) && ($past(grant) == 3'b000));
        end
    end
endmodule
`default_nettype wire
=== END FILE ===
